create or replace function ml_private.p3h_leap_role(s jsonb,a integer) returns boolean language sql stable set search_path=pg_catalog,ml_private as $$select ml_private.p3h_enabled(s) and s#>>array['players',a::text,'character']='character-035'$$;
create or replace function ml_private.p3h_pending_birth(s jsonb,a integer) returns boolean language sql stable set search_path=pg_catalog,ml_private as $$select coalesce(ml_private.p3h_leap_role(s,a) and s#>>array['players',a::text,'cell']='' and s#>array['stage3','h','birth',a::text]='null'::jsonb and s#>>array['stage4','offMap',a::text]='true',false)$$;
create or replace function ml_private.p3h_birth_cells(s jsonb,a integer) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select coalesce(jsonb_agg(c->'id' order by n),'[]') from jsonb_array_elements(ml_private.game_data(s,'cells')) with ordinality q(c,n) where ml_private.p3h_leap_role(s,a) and ml_private.stage4_board_entry(s,a,c->>'id') and not exists(select 1 from ml_private.arr(s->'players') p where (p->>'seat')::int<>a and ml_private.stage4_on_board(s,(p->>'seat')::int) and ml_private.p3h_blocks(s,a,(p->>'seat')::int) and p->'cell'=c->'id')$$;
create or replace function ml_private.p3h_birth_begin(s jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare a integer;cells jsonb;begin
 select (v->>'seat')::int into a from ml_private.arr(s->'players') v where ml_private.p3h_leap_role(s,(v->>'seat')::int);if a is null then return s;end if;
 s:=jsonb_set(s,'{stage3,h,birth}','[null,null,null,null]');s:=jsonb_set(s,array['stage4','offMap',a::text],'true');cells:=ml_private.p3h_birth_cells(s,a);perform ml_private.need(jsonb_array_length(cells)>0,'自定义出生没有合法空格');return ml_private.select_choice(s,'h-birth',a,at,jsonb_build_object('cells',cells));end $$;
create or replace function ml_private.p3h_birth_choose(s jsonb,cmd jsonb,at double precision,timeout boolean) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare c jsonb:=s->'choice';a integer:=(c->>'actor')::int;cells jsonb:=ml_private.p3h_birth_cells(s,a);cell text:=case when timeout then cells->>0 else cmd->>'cell' end;i integer;begin
 perform ml_private.need(cmd->'choice'=c->'id','选择窗口已过期');perform ml_private.need((cmd->>'actor')::int=a,'请交给待选择的座位操作');perform ml_private.need(ml_private.p3h_pending_birth(s,a) and cell is not null and c->'cells' ? cell and cells ? cell,'请选择合法的自定义出生格');
 s:=jsonb_set(s,array['players',a::text,'cell'],to_jsonb(cell));s:=jsonb_set(s,array['stage4','offMap',a::text],'false');s:=jsonb_set(s,array['stage3','h','birth',a::text],to_jsonb(cell));s:=ml_private.emit(s,'teleport','S'||(a+1)||' 世界是多元的：出生于'||cell);
 if timeout then s:=ml_private.emit(s,'timeout',ml_private.name(s,a)||' 选择超时：'||ml_private.p3h_choice_label(c->>'kind'));end if;s:=s||jsonb_build_object('choice',null,'phase','resolving');for i in 0..3 loop s:=ml_private.draw(s,i,4);end loop;return ml_private.start_round(s,at);end $$;
create or replace function ml_private.p3h_leap_cells(s jsonb,a integer) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select coalesce(jsonb_agg(c->'id' order by n),'[]') from jsonb_array_elements(ml_private.game_data(s,'cells')) with ordinality q(c,n) where ml_private.p3h_leap_role(s,a) and ml_private.stage4_on_board(s,a) and s#>>array['players',a::text,'moved']<>'true' and coalesce(s#>>array['stage3','c','blocked',a::text],'false')<>'true' and not ml_private.stage3_mount_blocked(s,a) and c->>'id'<>s#>>array['players',a::text,'cell'] and ml_private.stage4_board_empty(s,a,c->>'id',jsonb_build_array(a))$$;
create or replace function ml_private.p3h_respect_cells(s jsonb,a integer,target integer,region text) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare cell text;actual text;result jsonb:='[]';begin
 if not ml_private.p3h_leap_role(s,a) or not ml_private.stage4_on_board(s,a) or not ml_private.stage4_on_board(s,target) or a=target or ml_private.region_at(s->>'version',s#>>array['players',a::text,'cell'])<>region or ml_private.region_at(s->>'version',s#>>array['players',target::text,'cell'])<>region or not ml_private.p3h_active_allowed(s,a) or not ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',a,'roleModifiers','[]'::jsonb),target,s#>>array['players',target::text,'character']) then return result;end if;
 for cell in select v->>'id' from ml_private.arr(ml_private.game_data(s,'cells')) v loop
  if ml_private.region_at(s->>'version',cell)=region or not ml_private.stage4_board_empty(s,target,cell,jsonb_build_array(target)) or not ml_private.stage3_can_enter(s,target,cell) then continue;end if;actual:=ml_private.playtest_relocation_cell(s,target,s#>>array['players',target::text,'cell'],cell);if actual is not null and ml_private.region_at(s->>'version',actual)<>region then result:=result||jsonb_build_array(cell);end if;
 end loop;return result;end $$;
create or replace function ml_private.p3h_leap_move(s jsonb,cmd jsonb) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare a integer:=(cmd->>'actor')::int;cell text:=cmd->>'cell';origin text:=s#>>array['players',a::text,'cell'];region text;root text:=ml_private.p3e_root(s);cost integer;used integer;target integer;original jsonb;jobs jsonb:='[]';begin
 perform ml_private.need(jsonb_typeof(cmd->'cell')='string' and ml_private.p3h_leap_cells(s,a) ? cell,'Leap请选择全图合法空格');region:=ml_private.region_at(s->>'version',cell);select coalesce(jsonb_agg(v order by n),'[]') into original from jsonb_array_elements(s->'order') with ordinality q(v,n) where (v#>>'{}')::int<>a and ml_private.stage4_on_board(s,(v#>>'{}')::int) and ml_private.region_at(s->>'version',s#>>array['players',v#>>'{}','cell'])=region;
 cost:=case when ml_private.stage3_equipped(s,a,'basic-071') then 0 else ml_private.stage3_fixed_cost(s,a,ml_private.stage4_location_move_cost(s,a)) end;perform ml_private.need((s#>>array['players',a::text,'ap'])::int>=cost,'移动需要1AP');s:=ml_private.p3d_pay(s,a,cost);used:=(s#>>array['stage3','basicUsed',a::text])::int+1;s:=jsonb_set(s,array['stage3','basicUsed',a::text],to_jsonb(used));s:=jsonb_set(s,array['players',a::text,'moved'],to_jsonb(used>=case when s#>>array['stage3','doubleMove',a::text]='true' then 2 else 1 end));
 s:=ml_private.stage3_relocate(s,a,cell,true);jobs:=s->'_relocationTasks';s:=s-'_relocationTasks';for target in select (v#>>'{}')::int from ml_private.arr(original) v loop jobs:=jobs||jsonb_build_array(ml_private.stage3_task('h-respect',jsonb_build_object('actor',a,'target',target,'data',jsonb_build_object('from',origin,'to',cell,'region',region,'root',root))));end loop;s:=jsonb_set(s,'{queue}',(s->'queue')||jobs);return ml_private.emit(s,'cost','S'||(a+1)||' Leap基础传送支付'||cost||'AP，不掷移动骰');end $$;
create or replace function ml_private.p3h_leap_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare a integer:=(t->>'actor')::int;target integer:=(t->>'target')::int;d jsonb:=t->'data';cells jsonb;gate jsonb;begin
 if not ml_private.p3h_enabled(s) or t->>'action'<>'h-respect' then return s||jsonb_build_object('_hHandled',false);end if;
 if s#>>array['players',a::text,'cell']=d->>'from' then return s||jsonb_build_object('_hHandled',true);end if;s:=jsonb_set(s,'{stage3,e,current}',d->'root');cells:=ml_private.p3h_respect_cells(s,a,target,d->>'region');if jsonb_array_length(cells)=0 then return s||jsonb_build_object('_hHandled',true);end if;
 gate:=ml_private.p3e_gate(s,target,a,jsonb_build_array(t),d->>'root');if gate is not null then return ml_private.stage3_prepend(s,gate)||jsonb_build_object('_hHandled',true);end if;return ml_private.select_choice(s,'h-respect',a,at,jsonb_build_object('source',target,'cells',cells,'data',d))||jsonb_build_object('_hHandled',true);end $$;
create or replace function ml_private.p3h_leap_choose(s jsonb,cmd jsonb,at double precision,timeout boolean) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare c jsonb:=s->'choice';a integer:=(c->>'actor')::int;target integer:=(c->>'source')::int;d jsonb:=c->'data';cell text:=cmd->>'cell';begin
 if not ml_private.p3h_enabled(s) or c->>'kind'<>'h-respect' then return s||jsonb_build_object('_hHandled',false);end if;
 if not timeout and cell is not null then perform ml_private.need(c->'cells' ? cell and ml_private.p3h_respect_cells(s,a,target,d->>'region') ? cell,'respect请选择地区之外的合法空格');s:=jsonb_set(s,'{stage3,e,current}',d->'root');s:=s||jsonb_build_object('_eCause',jsonb_build_object('source',a,'root',ml_private.p3e_root(s)));s:=ml_private.stage3_relocate(s,target,cell,false,false);s:=s-'_eCause';s:=ml_private.stage3_prepend(s,s->'_relocationTasks')-'_relocationTasks';end if;return s||jsonb_build_object('_hHandled',true);end $$;
